head.script:
scwin.onpageload = function() {
	for (var i = 0; i < 7; i++) dataList1.insertRow();
};

scwin.gridView1_oncontextopen = function(row, col) {
	var appendMenu = [{ label: "특별한 컬럼 숨기기", userMenuId: "userColumnHide", className: "userMenu" }];
	for (var i = 1; i <= 19; i++) {
		appendMenu.push({ label: "메뉴 테스트" + i, userMenuId: "userTest" + i, className: "testMenu" + i });
	}
	return {
		// 특정 항목의 시스템 메뉴를 보여주지 않습니다.
		hideSystemMenu: ["ColumnHide", "ColumnFix", "ColumnAdjustWidth", "ColumnAdjustAuto", "Group", "ColumnAdjustAutoNone"],
		// 시스템 메뉴 아래에, 사용자 메뉴를 추가합니다(메뉴 높이를 키움).
		appendMenu: appendMenu
	};
};

// 좌표 없는 contextmenu 이벤트 발생
scwin.rightClick = function(id) {
	var el = document.getElementById(id) || document.getElementById("mf_" + id);
	var evt = document.createEvent('MouseEvents');
	evt.initEvent('contextmenu', true, false);
	el.dispatchEvent(evt);
};

scwin.checkVal = function() {
	var el = document.getElementById('gridView1_contextMenu_list') || document.getElementById('mf_gridView1_contextMenu_list');
	return el.getBoundingClientRect().top + window.pageYOffset == 0;
};
